import{_ as e,c as a,o as i,ae as s}from"./chunks/framework.Cd-3tpCq.js";const b=JSON.parse('{"title":"Catalog Attribute — Mass Delete (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-attribute-mass-delete","title":"Mass Delete Attributes","description":"Delete a batch of user-defined attributes in one mutation. The whole batch is pre-validated — if any id is a system attribute, nothing is deleted.","query":"mutation MassDeleteAttributes($input: createAdminAttributeMassDeleteInput!) {\\n  createAdminAttributeMassDelete(input: $input) {\\n    adminAttributeMassDelete {\\n      id\\n      deleted\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"indices\\": [24, 31]\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminAttributeMassDelete\\": {\\n      \\"adminAttributeMassDelete\\": {\\n        \\"id\\": \\"/api/admin/attribute_mass_deletes/1\\",\\n        \\"deleted\\": [24, 31],\\n        \\"message\\": \\"Attributes deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/attributes/attributes-mass-delete.md","filePath":"api/graphql-api/admin/catalog/attributes/attributes-mass-delete.md"}'),n={name:"api/graphql-api/admin/catalog/attributes/attributes-mass-delete.md"};function d(r,t,o,l,u,c){return i(),a("div",null,t[0]||(t[0]=[s('<h1 id="catalog-attribute-—-mass-delete-graphql" tabindex="-1">Catalog Attribute — Mass Delete (GraphQL) <a class="header-anchor" href="#catalog-attribute-—-mass-delete-graphql" aria-label="Permalink to &quot;Catalog Attribute — Mass Delete (GraphQL)&quot;">​</a></h1><p>Bulk-deletes a batch of user-defined attributes in a single mutation. <code>indices</code> is the list of attribute ids to delete. The batch is pre-validated: if any id belongs to a system attribute (<code>isUserDefined = 0</code>), the entire batch is rejected and nothing is deleted. Non-existent ids are silently skipped and do not appear in <code>deleted</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/graphql-api/admin/catalog/attributes/">Attributes overview</a> for how attributes, options, and families fit together.</p></div><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>indices</code></td><td><code>[Int!]!</code></td><td>Attribute ids to delete</td></tr></tbody></table><p>A batch containing a system attribute returns an <code>errors[]</code> entry <code>System attributes cannot be deleted.</code> and no row is touched.</p><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',7)]))}const h=e(n,[["render",d]]);export{b as __pageData,h as default};
